#include <vector>
#include <string>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    long long maxTotalValueCovered(std::vector<int>& nums, std::string s) {
        int n = nums.size();
        std::unordered_set<int> covered;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '1') {
                covered.insert(i);
                if (i - 1 >= 0 && nums[i - 1] > nums[i]) covered.insert(i - 1);
                if (i + 1 < n && nums[i + 1] > nums[i]) covered.insert(i + 1);
            }
        }
        long long ans = 0;
        for (int idx : covered) ans += nums[idx];
        return ans;
    }
};

import java.util.*;

class Solution {
    public long maxTotalValueCovered(int[] nums, String s) {
        int n = nums.length;
        Set<Integer> covered = new HashSet<>();
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') {
                covered.add(i);
                if (i - 1 >= 0 && nums[i - 1] > nums[i]) covered.add(i - 1);
                if (i + 1 < n && nums[i + 1] > nums[i]) covered.add(i + 1);
            }
        }
        long ans = 0;
        for (int idx : covered) ans += nums[idx];
        return ans;
    }
}

